# Code generated by Claude
"""Per-tick diagnostic extract of a recorded run (read-only; changes no controller or parameter).

Replays a recording with replay_run(video="none") so the states are verified bit-identical to the run, and reads the simulator
state at the start of every control tick through the replay's step hook. Writes one CSV row per tick.

    python experiments/bounce_diag_extract.py <recording_dir> <out_csv>

Columns (both arms, the 7 arm joints of each: L1..L7 / R1..R7):
  q        measured joint angle at the tick's start (rad)
  qd       measured joint velocity at the tick's start (rad/s)
  ctrl     actuator target the tick applied (the recording's ctrl, mean over the tick's 5 physics steps): q_cmd + ff/kp
  ff       feedforward offset total: the torque tau_ff at the tick's start, from src/gravity_ff (the arm's own gravity + the held term)
  ff_grav  the arm's own gravity part of tau_ff (N m)
  ff_held  the held-object part of tau_ff (N m): m_meas g J_z of the pad centre, m_meas from the recording's heldmass
  qcmd     ctrl - ff/kp: the skill's own command (rad), i.e. the command before the feedforward
  force    applied actuator force, mean over the tick's 5 steps (N m); the servo's own torque
Beaker (task_beaker, world frame at the tick's start): bx, by, bz (m); tilt (deg from vertical); bvx..bvz (m/s); bwx..bwz (rad/s, body
angular velocity), brx, bry, brz (beaker centre relative to the left pad centre, in the left hand's frame, m), n_bc (contacts of the beaker),
f_bc (sum of normal contact force on the beaker, N).
Gripper (left): fl1, fl2 (finger joints, m), gl (gripper ctrl), gf_l (recorded grip force), hm_l, hm_r (recorded held mass, kg).
Phase: the label of the last recorded label at or before the tick (the run's own labels, from the recording meta).
"""

import csv
import sys
from pathlib import Path

import mujoco
import numpy as np

sys.path.insert(0, str(Path(__file__).resolve().parent.parent))

from src import gravity_ff                                           # noqa: E402
from src.replay import build_model, replay_run                       # noqa: E402
from src.run_record import load_recording                             # noqa: E402

SIDES = ("left", "right")
JOINTS = range(1, 8)


def main(rec_dir, out_csv):
    rec = load_recording(rec_dir)
    meta = rec["meta"]
    steps_per_tick = int(meta["steps_per_tick"])
    n_ticks = len(rec["ctrl"])
    model, _data0, _reset = build_model(meta)                      # a separate copy of the same model, for Jacobians and names
    ff = gravity_ff.ArmGravityFeedforward.from_model(model)        # the controller's own feedforward class (read only here)
    kp = {}
    for s in SIDES:
        for i in JOINTS:
            a = mujoco.mj_name2id(model, mujoco.mjtObj.mjOBJ_ACTUATOR, f"{s}_joint{i}_ctrl")
            kp[(s, i)] = model.actuator_gainprm[a, 0]
    act = {(s, i): mujoco.mj_name2id(model, mujoco.mjtObj.mjOBJ_ACTUATOR, f"{s}_joint{i}_ctrl") for s in SIDES for i in JOINTS}
    dof = {(s, i): int(model.jnt_dofadr[model.actuator_trnid[act[(s, i)], 0]]) for s in SIDES for i in JOINTS}
    qadr = {(s, i): int(model.jnt_qposadr[model.actuator_trnid[act[(s, i)], 0]]) for s in SIDES for i in JOINTS}
    fing = {k: mujoco.mj_name2id(model, mujoco.mjtObj.mjOBJ_JOINT, f"openarm_left_finger_joint{k}") for k in (1, 2)}
    fing_qadr = {k: int(model.jnt_qposadr[fing[k]]) for k in (1, 2)}
    gripper_act = mujoco.mj_name2id(model, mujoco.mjtObj.mjOBJ_ACTUATOR, "left_gripper_ctrl")
    beaker = mujoco.mj_name2id(model, mujoco.mjtObj.mjOBJ_BODY, "task_beaker")
    hand_tcp = model.body("openarm_left_hand_tcp").id
    pad_local = np.asarray(ff.pads["left"][1], float)
    labels = sorted(meta.get("labels", []), key=lambda l: l["tick"])
    label_ticks = [l["tick"] for l in labels]
    scratch = mujoco.MjData(model)
    res6 = np.zeros(6)
    f6 = np.zeros(6)

    cols = ["tick", "t_sim", "phase"]
    for s in SIDES:
        tag = "L" if s == "left" else "R"
        for i in JOINTS:
            cols += [f"{tag}{i}_{k}" for k in ("q", "qd", "ctrl", "ff", "ff_grav", "ff_held", "qcmd", "force")]
    cols += ["bx", "by", "bz", "tilt", "bvx", "bvy", "bvz", "bwx", "bwy", "bwz", "brx", "bry", "brz", "n_bc", "f_bc"]
    cols += ["fl1", "fl2", "gl", "gf_l", "hm_l", "hm_r"]

    rows = {}
    force_acc = np.zeros(model.nu)
    state = {"start": None}

    def label_at(tick):
        k = np.searchsorted(label_ticks, tick, side="right") - 1
        return labels[k]["label"] if k >= 0 else ""

    def tick_start_row(j, d):
        """Row j from the state at the start of tick j (the data after step 5j)."""
        row = {"tick": j, "t_sim": f"{d.time:.6f}", "phase": label_at(j)}
        # feedforward at this pose, with and without the held mass (the held mass of tick j from the recording)
        for s, idx in (("left", 0), ("right", 1)):
            gravity_ff.set_held_mass(model, s, float(rec["heldmass"][j][idx]) or None)
        tau_total = ff.torques(d).copy()
        for s in ("left", "right"):
            gravity_ff.set_held_mass(model, s, None)
        tau_grav = ff.torques(d).copy()
        ids = list(ff.ids)
        tot = dict(zip(ids, tau_total))
        grv = dict(zip(ids, tau_grav))
        for s in SIDES:
            tag = "L" if s == "left" else "R"
            for i in JOINTS:
                a = act[(s, i)]
                q = d.qpos[qadr[(s, i)]]
                qd = d.qvel[dof[(s, i)]]
                c = rec["ctrl"][j][:, a].mean()
                ffv = tot[a]
                row[f"{tag}{i}_q"] = f"{q:.6f}"
                row[f"{tag}{i}_qd"] = f"{qd:.6f}"
                row[f"{tag}{i}_ctrl"] = f"{c:.6f}"
                row[f"{tag}{i}_ff"] = f"{ffv:.4f}"
                row[f"{tag}{i}_ff_grav"] = f"{grv[a]:.4f}"
                row[f"{tag}{i}_ff_held"] = f"{ffv - grv[a]:.4f}"
                row[f"{tag}{i}_qcmd"] = f"{c - ffv / kp[(s, i)]:.6f}"
        # beaker
        R = d.xmat[beaker].reshape(3, 3)
        row["bx"], row["by"], row["bz"] = (f"{v:.6f}" for v in d.xpos[beaker])
        row["tilt"] = f"{np.degrees(np.arccos(np.clip(R[2, 2], -1, 1))):.4f}"
        mujoco.mj_objectVelocity(model, d, mujoco.mjtObj.mjOBJ_BODY, beaker, res6, 0)
        row["bwx"], row["bwy"], row["bwz"] = (f"{v:.6f}" for v in res6[:3])
        row["bvx"], row["bvy"], row["bvz"] = (f"{v:.6f}" for v in res6[3:])
        Rt = d.xmat[hand_tcp].reshape(3, 3)
        pad = d.xpos[hand_tcp] + Rt @ pad_local
        rel = Rt.T @ (d.xpos[beaker] - pad)
        row["brx"], row["bry"], row["brz"] = (f"{v:.6f}" for v in rel)
        n, fsum = 0, 0.0
        for ci in range(d.ncon):
            con = d.contact[ci]
            if beaker in (model.geom_bodyid[con.geom1], model.geom_bodyid[con.geom2]):
                n += 1
                mujoco.mj_contactForce(model, d, ci, f6)
                fsum += abs(f6[0])
        row["n_bc"], row["f_bc"] = str(n), f"{fsum:.4f}"
        # gripper
        row["fl1"] = f"{d.qpos[fing_qadr[1]]:.6f}"
        row["fl2"] = f"{d.qpos[fing_qadr[2]]:.6f}"
        row["gl"] = f"{rec['ctrl'][j][:, gripper_act].mean():.6f}"
        row["gf_l"] = f"{rec['gripforce'][j][0]:.4f}"
        row["hm_l"] = f"{rec['heldmass'][j][0]:.4f}"
        row["hm_r"] = f"{rec['heldmass'][j][1]:.4f}"
        return row

    def on_step(step_count, d):
        force_acc[:] += d.actuator_force                          # every physics step of the tick
        if step_count % steps_per_tick == 0:
            m = step_count // steps_per_tick                       # tick m-1 has just finished; d is the start of tick m
            j_done = m - 1
            if j_done in rows:
                rows[j_done].update({f"_force_{k}": v for k, v in enumerate(force_acc / steps_per_tick)})
            force_acc[:] = 0.0
            if m < n_ticks:
                rows[m] = tick_start_row(m, d)

    report = replay_run(rec_dir, video="none", verify=True, step_hook=on_step, quiet=True)
    print("replay ok", report["ok"], "ticks", report["ticks"], "mismatch", report["mismatch"], flush=True)
    # the force column is finished one tick later (the 5 steps of that tick), so write rows after the run
    tmp = Path(out_csv).with_name(Path(out_csv).name + ".tmp")
    with open(tmp, "w", newline="") as fh:
        w = csv.writer(fh)
        w.writerow(cols)
        for j in sorted(rows):
            r = rows[j]
            for s in SIDES:
                tag = "L" if s == "left" else "R"
                for i in JOINTS:
                    r[f"{tag}{i}_force"] = f"{r.get(f'_force_{act[(s, i)]}', float('nan')):.4f}"
            w.writerow([r.get(c, "") for c in cols])
    tmp.replace(out_csv)
    print("wrote", out_csv, len(rows), "rows", flush=True)


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
